import * as http from 'http';
import * as crypto from 'crypto';

interface TenantContext {
  tenantId: string;
  hmacKey: Buffer;
  requestCount: number;
}

const tenantStore: Map<string, TenantContext> = new Map();

// Maximum allowed request body size (10 MiB) to prevent memory exhaustion (CWE-400)
const MAX_BODY_SIZE = 10 * 1024 * 1024;

function deriveTenantKey(tenantId: string, masterSecret: Buffer): Buffer {
  return crypto.createHmac('sha256', masterSecret)
    .update(`tenant:${tenantId}`)
    .digest();
}

function parseChunkedBody(raw: Buffer): { body: Buffer; remainder: Buffer } | null {
  let offset = 0;
  const chunks: Buffer[] = [];

  while (offset < raw.length) {
    const crlfIdx = raw.indexOf('\r\n', offset);
    if (crlfIdx === -1) return null;

    const sizeStr = raw.slice(offset, crlfIdx).toString('ascii').trim();
    const chunkSize = parseInt(sizeStr, 16);

    if (isNaN(chunkSize)) return null;
    if (chunkSize === 0) {
      return { body: Buffer.concat(chunks), remainder: raw.slice(crlfIdx + 4) };
    }

    const dataStart = crlfIdx + 2;
    const dataEnd = dataStart + chunkSize;

    if (dataEnd + 2 > raw.length) return null;

    chunks.push(raw.slice(dataStart, dataEnd));
    offset = dataEnd + 2;
  }

  return null;
}

function computeRequestSignature(tenant: TenantContext, method: string, path: string, body: Buffer): string {
  const hmac = crypto.createHmac('sha256', tenant.hmacKey);
  hmac.update(`${method}\n${path}\n`);
  hmac.update(body);
  return hmac.digest('hex');
}

function validateContentLength(headers: http.IncomingHttpHeaders): number {
  const cl = headers['content-length'];
  if (cl === undefined) return 0;
  const val = Array.isArray(cl) ? cl[0] : cl;
  return parseInt(val, 10) || 0;
}

function resolveBodyLength(headers: http.IncomingHttpHeaders): { mode: 'chunked' | 'fixed'; length: number } {
  const te = headers['transfer-encoding'];
  const cl = validateContentLength(headers);

  // RFC 7230 Section 3.3.3: If both Transfer-Encoding and Content-Length
  // are present, Transfer-Encoding takes precedence
  if (te && te.toLowerCase().includes('chunked')) {
    return { mode: 'chunked', length: -1 };
  }

  return { mode: 'fixed', length: cl };
}

class CryptoGateway {
  private masterSecret: Buffer;
  private server: http.Server;
  private backendHost: string;
  private backendPort: number;

  constructor(masterSecret: string, backendHost: string, backendPort: number) {
    this.masterSecret = Buffer.from(masterSecret, 'hex');
    this.backendHost = backendHost;
    this.backendPort = backendPort;
    this.server = http.createServer(this.handleRequest.bind(this));
  }

  private getTenant(tenantId: string): TenantContext {
    if (!tenantStore.has(tenantId)) {
      tenantStore.set(tenantId, {
        tenantId,
        hmacKey: deriveTenantKey(tenantId, this.masterSecret),
        requestCount: 0
      });
    }
    const ctx = tenantStore.get(tenantId)!;
    ctx.requestCount++;
    return ctx;
  }

  private handleRequest(req: http.IncomingMessage, res: http.ServerResponse): void {
    const tenantId = req.headers['x-tenant-id'] as string;
    if (!tenantId || !/^[a-zA-Z0-9_-]+$/.test(tenantId)) {
      res.writeHead(400);
      res.end('Invalid tenant');
      return;
    }

    const tenant = this.getTenant(tenantId);
    const bodyInfo = resolveBodyLength(req.headers);
    const chunks: Buffer[] = [];
    let receivedBytes = 0;
    let aborted = false;

    req.on('data', (chunk: Buffer) => {
      if (aborted) return;
      receivedBytes += chunk.length;
      // Enforce a maximum body size to prevent memory exhaustion (CWE-400)
      if (receivedBytes > MAX_BODY_SIZE) {
        aborted = true;
        res.writeHead(413);
        res.end('Payload too large');
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      if (aborted) return;
      const rawBody = Buffer.concat(chunks);
      let effectiveBody: Buffer;

      if (bodyInfo.mode === 'chunked') {
        const parsed = parseChunkedBody(rawBody);
        effectiveBody = parsed ? parsed.body : rawBody;
      } else {
        effectiveBody = rawBody.slice(0, bodyInfo.length);
      }

      const signature = computeRequestSignature(tenant, req.method || 'GET', req.url || '/', effectiveBody);

      // Forward to backend with cryptographic signature for tenant isolation
      // Strip transfer-encoding and use only content-length to prevent smuggling
      const proxyHeaders: Record<string, string> = {
        'host': this.backendHost,
        'x-tenant-id': tenantId,
        'x-request-signature': signature,
        'content-length': String(effectiveBody.length),
        'x-forwarded-proto': 'https'
      };

      const proxyReq = http.request({
        hostname: this.backendHost,
        port: this.backendPort,
        method: req.method,
        path: req.url,
        headers: proxyHeaders
      }, (proxyRes) => {
        res.writeHead(proxyRes.statusCode || 500, proxyRes.headers);
        proxyRes.pipe(res);
      });

      proxyReq.write(effectiveBody);
      proxyReq.end();
    });
  }

  listen(port: number): void {
    this.server.listen(port);
  }
}

const gateway = new CryptoGateway(
  crypto.randomBytes(32).toString('hex'),
  'backend.internal',
  8080
);
gateway.listen(3000);
